  "identifier": "my_pack:my_entity",
  "entity_version": {
    "upgrades": [
      { "upgrade_to": 1, "name": "my_pack:upgrade_v1" },
      { "upgrade_to": 2, "name": "my_pack:upgrade_v2" },
      { "upgrade_to": 3, "name": "my_pack:upgrade_v3" }
    ]
  }
}
