input.command:
$root = "C:\Users\t24j007\project\SkyCitadel"
$errs = @()

# 1. JSON parse check
$jsons = Get-ChildItem -Recurse -Filter *.json $root
foreach ($f in $jsons) {
  try { Get-Content $f.FullName -Raw -Encoding utf8 | ConvertFrom-Json | Out-Null }
  catch { $errs += "JSON PARSE: $($f.Name): $($_.Exception.Message)" }
}
Write-Host "[1] JSON parse: $($jsons.Count) files checked"

# 2. UUID uniqueness
$uuids = @()
foreach ($m in @("$root\behavior_packs\SkyCitadel_BP\manifest.json", "$root\resource_packs\SkyCitadel_RP\manifest.json")) {
  $j = Get-Content $m -Raw -Encoding utf8 | ConvertFrom-Json
  $uuids += $j.header.uuid
  foreach ($mod in $j.modules) { $uuids += $mod.uuid }
}
$dupes = $uuids | Group-Object | Where-Object { $_.Count -gt 1 }
if ($dupes) { $errs += "UUID DUPLICATE: $($dupes.Name -join ', ')" }
Write-Host "[2] UUIDs: $($uuids.Count) total, duplicates: $(if($dupes){$dupes.Count}else{0})"

# 3. BP entity identifiers vs RP client entity identifiers
$bpIds = @(); Get-ChildItem "$root\behavior_packs\SkyCitadel_BP\entities\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $bpIds += $j.'minecraft:entity'.description.identifier
}
$rpIds = @(); Get-ChildItem "$root\resource_packs\SkyCitadel_RP\entity\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $rpIds += $j.'minecraft:client_entity'.description.identifier
}
foreach ($id in $bpIds) { if ($rpIds -notcontains $id) { $errs += "NO RP CLIENT DEF: $id" } }
Write-Host "[3] BP entities: $($bpIds.Count) / RP client defs: $($rpIds.Count)"

# 4. Loot table paths referenced by entities exist
Get-ChildItem "$root\behavior_packs\SkyCitadel_BP\entities\*.json" | ForEach-Object {
  $raw = Get-Content $_.FullName -Raw -Encoding utf8
  if ($raw -match '"table"\s*:\s*"([^"]+)"') {
    $t = $Matches[1]
    if (-not (Test-Path "$root\behavior_packs\SkyCitadel_BP\$t")) { $errs += "MISSING LOOT TABLE: $t (referenced by $($_.Name))" }
  }
}
Write-Host "[4] Loot table references checked"

# 5. sc: items referenced in loot tables exist as item definitions
$itemIds = @(); Get-ChildItem "$root\behavior_packs\SkyCitadel_BP\items\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $itemIds += $j.'minecraft:item'.description.identifier
}
Get-ChildItem -Recurse "$root\behavior_packs\SkyCitadel_BP\loot_tables\*.json" | ForEach-Object {
  $raw = Get-Content $_.FullName -Raw -Encoding utf8
  $ms = [regex]::Matches($raw, '"name"\s*:\s*"(sc:[^"]+)"')
  foreach ($m in $ms) {
    if ($itemIds -notcontains $m.Groups[1].Value) { $errs += "MISSING ITEM DEF: $($m.Groups[1].Value) (in $($_.Name))" }
  }
}
Write-Host "[5] Item defs: $($itemIds.Count) / loot references checked"

Write-Host "=============================="
if ($errs.Count -eq 0) { Write-Host "ALL CHECKS PASSED" } else { $errs | ForEach-Object { Write-Host "NG: $_" } }

$root = "C:\Users\t24j007\project\SkyCitadel"
$out = "$root\dist"
New-Item -ItemType Directory -Force $out | Out-Null
$zip = "$out\SkyCitadel_v0.1.0.zip"
if (Test-Path $zip) { Remove-Item $zip -Force }
Compress-Archive -Path "$root\behavior_packs", "$root\resource_packs" -DestinationPath $zip
$mcaddon = "$out\SkyCitadel_v0.1.0.mcaddon"
if (Test-Path $mcaddon) { Remove-Item $mcaddon -Force }
Rename-Item $zip $mcaddon
Get-Item $mcaddon | Select-Object Name, @{N='SizeKB';E={[math]::Round($_.Length/1KB,1)}}

