          "min_size": 4,
          "max_size": 6,
          "event": "minecraft:entity_born",
          "event_skip_count": 2
        },
        "minecraft:biome_filter": {
          "test": "has_biome_tag",
          "operator": "==",
          "value": "lush_caves"
        }
      }
    ]
  }
}
```

