    "randomize_rotation": true,
    "enforce_survivability_rules": true,
    "enforce_placement_rules": true,
    "may_attach_to": {
      "auto_rotate": false,
      "min_sides_must_attach": 1,
      "south": [
        "minecraft:grass",
        "minecraft:dirt"
      ]
    },
    "may_not_attach_to": {
      "south": {
        "name": "minecraft:dirt",
        "states": {
          "dirt_type": "coarse"
        }
      }
    }
  }
}
```

### Example - Placing a single carved pumpkin

Feature that places a randomly rotated single pumpkin or carved pumpkin block where carved pumpkins are less likely to appear.

```json
{ 
  "format_version": "1.21.40", 
  "minecraft:single_block_feature": { 
    "description": { 
      "identifier": "example:single_pumpkin_feature" 
    }, 
    "places_block": [ 
      { 
        "block": "minecraft:pumpkin", 
        "weight": 5 
      }, 
      { 
        "block": "minecraft:carved_pumpkin", 
        "weight": 1 
      } 
    ], 
    "randomize_rotation": true, 
    "enforce_survivability_rules": true, 
    "enforce_placement_rules": true, 
    "may_attach_to": { 
      "auto_rotate": false, 
      "min_sides_must_attach": 1, 
      "south": [ 
        "minecraft:grass", 
        "minecraft:dirt" 
      ] 
    }, 
    "may_not_attach_to": { 
      "south": { 
        "name": "minecraft:dirt", 
        "states": { 
          "dirt_type": "coarse" 
        } 
      }, 
      "diagonal": [ 
        "minecraft:stone", 
        "minecraft:gravel" 
      ] 
    } 
  } 
} 
```

### Example

Feature that supports either a single block or an array of weighted block descriptors.

```json
{ 
  "format_version": "1.21.30", 
  "minecraft:single_block_feature": { 
    "description": { 
      "identifier": "test:my_block_feature" 
    }, 
    "places_block": [ 
      { 
        "block": "minecraft:bee_nest", 
        "weight": 2 
      }, 
      { 
        "block": { 
          "name": "minecraft:beehive", 
          "states": { 
            "honey_level": 5 
          } 
        }, 
        "weight" :  1.5 
      }, 
      { 
        "block": { 
          "name": "minecraft:beehive", 
          "states": { 
            "honey_level": 0 
          } 
        }, 
        "weight" : 5 
      } 
    ], 
    "may_attach_to": { 
      "bottom": { 
        "name": "minecraft:grass" 
      } 
    } 
  } 
} 
```

