$root = "C:\Users\t24j007\project\SkyCitadel"
$errs = @()

# 1. JSON parse (all)
$jsons = Get-ChildItem -Recurse -Filter *.json $root | Where-Object { $_.FullName -notlike "*\dist\*" }
foreach ($f in $jsons) {
  try { Get-Content $f.FullName -Raw -Encoding utf8 | ConvertFrom-Json | Out-Null }
  catch { $errs += "JSON PARSE: $($f.Name): $($_.Exception.Message)" }
}
Write-Host "[1] JSON parse: $($jsons.Count) files"

# 2. Feature chain: rule -> cluster -> debris, identifier matches filename
$featDir = "$root\behavior_packs\SkyCitadel_BP\features"
$featIds = @{}
Get-ChildItem "$featDir\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $node = $j.PSObject.Properties | Where-Object { $_.Name -like "minecraft:*" } | Select-Object -First 1
  $id = $node.Value.description.identifier
  $featIds[$id] = $_.BaseName
  $expected = ($id -split ":")[1]
  if ($expected -ne $_.BaseName) { $errs += "FEATURE NAME MISMATCH: $id vs file $($_.Name)" }
}
$rule = Get-Content "$root\behavior_packs\SkyCitadel_BP\feature_rules\sky_ruin_rule.json" -Raw -Encoding utf8 | ConvertFrom-Json
$placed = $rule.'minecraft:feature_rules'.description.places_feature
if (-not $featIds.ContainsKey($placed)) { $errs += "RULE REFERENCES MISSING FEATURE: $placed" }
$cluster = Get-Content "$featDir\sky_ruin_cluster_feature.json" -Raw -Encoding utf8 | ConvertFrom-Json
$inner = $cluster.'minecraft:scatter_feature'.places_feature
if (-not $featIds.ContainsKey($inner)) { $errs += "CLUSTER REFERENCES MISSING FEATURE: $inner" }
Write-Host "[2] Feature chain: rule->$placed->$inner OK-check done ($($featIds.Count) features)"

# 3. Spawn rule identifiers match existing BP entities
$bpIds = @(); Get-ChildItem "$root\behavior_packs\SkyCitadel_BP\entities\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $bpIds += $j.'minecraft:entity'.description.identifier
}
Get-ChildItem "$root\behavior_packs\SkyCitadel_BP\spawn_rules\*.json" | ForEach-Object {
  $j = Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json
  $sid = $j.'minecraft:spawn_rules'.description.identifier
  if ($bpIds -notcontains $sid) { $errs += "SPAWN RULE FOR UNKNOWN ENTITY: $sid" }
}
Write-Host "[3] Spawn rules -> entity identifiers checked"

Write-Host "=============================="
