$root = "C:\Users\t24j007\project\SkyCitadel"
Add-Type -AssemblyName System.IO.Compression

# JSON検証
$errs = 0
Get-ChildItem -Recurse -Filter *.json $root | Where-Object { $_.FullName -notlike "*dist*" } | ForEach-Object {
  try { Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json | Out-Null }
  catch { $errs++; Write-Host "NG: $($_.Name)" }
}
Write-Host "JSON errors: $errs"
node --check "$root\behavior_packs\SkyCitadel_BP\scripts\main.js"
if ($?) { Write-Host "JS syntax: OK" }

$outFile = "$root\dist\SkyCitadel_v0.5.0.mcaddon"
if ([System.IO.File]::Exists($outFile)) { [System.IO.File]::Delete($outFile) }

$fs = [System.IO.File]::Open($outFile, [System.IO.FileMode]::CreateNew)
$zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
$bs = [char]92
$fsl = [char]47
$packs = @(
  "$root\behavior_packs\SkyCitadel_BP",
  "$root\resource_packs\SkyCitadel_RP"
)
foreach ($pack in $packs) {
  $packRoot = Get-Item -LiteralPath $pack
  $files = Get-ChildItem -Recurse -File -LiteralPath $pack
  foreach ($f in $files) {
    $rel = $f.FullName.Substring($packRoot.FullName.Length + 1)
    $rel = $rel.Replace($bs, $fsl)
    $entryName = $packRoot.Name + "/" + $rel
    $entry = $zip.CreateEntry($entryName, [System.IO.Compression.CompressionLevel]::Optimal)
    $entryStream = $entry.Open()
    $bytes = [System.IO.File]::ReadAllBytes($f.FullName)
    $entryStream.Write($bytes, 0, $bytes.Length)
    $entryStream.Close()
  }
}
$zip.Dispose()
$fs.Dispose()

# 検証
$za = [System.IO.Compression.ZipArchive]::new([System.IO.File]::OpenRead($outFile))
Write-Host "Entry count: $($za.Entries.Count)"
$setupEntry = $za.Entries | Where-Object { $_.FullName -eq "SkyCitadel_BP/functions/setup.mcfunction" }
Write-Host "setup.mcfunction present: $([bool]$setupEntry)"
$za.Dispose()

# 旧ファイル削除
if ([System.IO.File]::Exists("$root\dist\SkyCitadel_v0.4.1.mcaddon")) {
  [System.IO.File]::Delete("$root\dist\SkyCitadel_v0.4.1.mcaddon")
}
Get-ChildItem "$root\dist" | Select-Object Name, @{N='SizeKB';E={[math]::Round($_.Length/1KB,1)}}

