# Sky Citadel テクスチャリカラー: 輝度ベースのグラデーションマップ
Add-Type -AssemblyName System.Drawing

$dl  = "C:\Users\t24j007\AppData\Local\Temp\claude\C--Users-t24j007-project-Procson-shuukatsu-app\04e964e7-f37d-47e5-b374-edc966b10624\scratchpad\vanilla_tex"
$out = "C:\Users\t24j007\project\SkyCitadel\resource_packs\SkyCitadel_RP\textures\entity\sc"
New-Item -ItemType Directory -Force $out | Out-Null

# モブ別パレット: 輝度0/0.35/0.65/0.85/0.95に対応する5ストップ
$palettes = @{
  "fallen_sky_monarch" = @( @(14,10,26), @(55,45,95),  @(120,110,170), @(216,190,120), @(255,235,170) ) # 王: 紫紺×金
  "sky_knight"         = @( @(10,14,28), @(38,62,100), @(100,145,195), @(185,212,238), @(245,250,255) ) # 騎士: 鋼青
  "sky_guard"          = @( @(12,14,22), @(45,60,85),  @(95,125,160),  @(170,195,220), @(235,242,250) ) # 近衛: 暗鋼
  "sky_mage"           = @( @(16,10,30), @(60,45,110), @(120,100,185), @(190,175,235), @(245,240,255) ) # 魔導士: 菫
  "gargoyle"           = @( @(12,12,16), @(55,58,66),  @(110,115,125), @(175,180,190), @(230,235,240) ) # 石像: 石灰
  "gargoyle_charging"  = @( @(20,10,10), @(80,45,45),  @(150,90,90),   @(210,150,150), @(255,220,210) ) # 起動時: 赤熱
  "sky_golem"          = @( @(18,22,34), @(70,85,110), @(140,160,185), @(205,220,235), @(255,245,215) ) # 巨神: 淡鋼×金
  "weak_core"          = @( @(6,20,30),  @(20,80,110), @(60,170,200),  @(160,235,250), @(230,255,255) ) # 核: 氷青の輝き
}
$sources = @{
  "fallen_sky_monarch" = "wither_skeleton.png"
  "sky_knight"         = "vindicator.png"
  "sky_guard"          = "pillager.png"
  "sky_mage"           = "evoker.png"
  "gargoyle"           = "vex.png"
  "gargoyle_charging"  = "vex_charging.png"
  "sky_golem"          = "iron_golem.png"
  "weak_core"          = "endercrystal.png"
}
$stops = @(0.0, 0.35, 0.65, 0.85, 0.95)

function Map-Color([double]$lum, $pal) {
  if ($lum -ge $stops[4]) { return $pal[4] }
  for ($i = 0; $i -lt 4; $i++) {
    if ($lum -le $stops[$i + 1]) {
      $t = ($lum - $stops[$i]) / ($stops[$i + 1] - $stops[$i])
      $a = $pal[$i]; $b = $pal[$i + 1]
      return @(
        [int]($a[0] + ($b[0] - $a[0]) * $t),
        [int]($a[1] + ($b[1] - $a[1]) * $t),
        [int]($a[2] + ($b[2] - $a[2]) * $t)
      )
    }
  }
  return $pal[4]
}

foreach ($name in $sources.Keys) {
  $srcPath = Join-Path $dl $sources[$name]
  $src = [System.Drawing.Bitmap]::FromFile($srcPath)
  $bmp = New-Object System.Drawing.Bitmap($src.Width, $src.Height, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
  for ($y = 0; $y -lt $src.Height; $y++) {
    for ($x = 0; $x -lt $src.Width; $x++) {
      $c = $src.GetPixel($x, $y)
      if ($c.A -eq 0) { continue }
      $lum = (0.299 * $c.R + 0.587 * $c.G + 0.114 * $c.B) / 255.0
      $rgb = Map-Color $lum $palettes[$name]
      $bmp.SetPixel($x, $y, [System.Drawing.Color]::FromArgb($c.A, $rgb[0], $rgb[1], $rgb[2]))
    }
  }
  $outPath = Join-Path $out "$name.png"
  $bmp.Save($outPath, [System.Drawing.Imaging.ImageFormat]::Png)
  $src.Dispose(); $bmp.Dispose()
  Write-Host "OK: $name.png ($($src.Width)x$($src.Height))"
}

