  try { Get-Content $_.FullName -Raw -Encoding utf8 | ConvertFrom-Json | Out-Null } catch { $errs++; Write-Host "NG: $($_.Name)" }
}
Write-Host "JSON errors: $errs"
$outFile = "$root\dist\SkyCitadel_v0.10.0.mcaddon"
if ([System.IO.File]::Exists($outFile)) { [System.IO.File]::Delete($outFile) }
$fs = [System.IO.File]::Open($outFile, [System.IO.FileMode]::CreateNew)
$zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
$bs = [char]92
foreach ($pack in @("$root\behavior_packs\SkyCitadel_BP", "$root\resource_packs\SkyCitadel_RP")) {
  $packRoot = Get-Item -LiteralPath $pack
  foreach ($f in (Get-ChildItem -Recurse -File -LiteralPath $pack)) {
    $rel = $f.FullName.Substring($packRoot.FullName.Length + 1).Replace($bs, "/")
    $entry = $zip.CreateEntry($packRoot.Name + "/" + $rel, [System.IO.Compression.CompressionLevel]::Optimal)
    $es = $entry.Open(); $bytes = [System.IO.File]::ReadAllBytes($f.FullName); $es.Write($bytes, 0, $bytes.Length); $es.Close()
  }
}
$zip.Dispose(); $fs.Dispose()
$za = [System.IO.Compression.ZipArchive]::new([System.IO.File]::OpenRead($outFile))
Write-Host "Entry count: $($za.Entries.Count) / functions: $(($za.Entries | Where-Object { $_.FullName -like '*mcfunction' }).Count)"
$za.Dispose()
if ([System.IO.File]::Exists("$root\dist\SkyCitadel_v0.9.0.mcaddon")) { [System.IO.File]::Delete("$root\dist\SkyCitadel_v0.9.0.mcaddon") }
Get-ChildItem "$root\dist" | Select-Object Name, @{N='SizeKB';E={[math]::Round($_.Length/1KB,1)}}

