function dist2(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return dx * dx + dy * dy + dz * dz;
}

// ============================================================
// イベントシステム（試練・ウェーブ戦・橋崩落・封印儀式）
// 進行フラグは dynamic property に永続化（リログ耐性 / Phase10方針）
// ============================================================
function inBox(l, b) {
  return l.x >= b.x1 && l.x <= b.x2 && l.y >= b.y1 && l.y <= b.y2 && l.z >= b.z1 && l.z <= b.z2;
}
function playersIn(box) {
  return world.getAllPlayers().filter(
    (p) => p.dimension.id === "minecraft:overworld" && inBox(p.location, box)
  );
}

// ---- ① 大聖堂の試練（強制戦闘 → 島の鍵） ---------------------------------
const TRIAL_BOX = { x1: 966, y1: 198, x2: 1034, y2: 232, z1: 1066, z2: 1162 };
const TRIAL_SEL = "@a[x=966,y=198,z=1066,dx=68,dy=34,dz=96]";
let trialActive = false;

function cathedralTrialTick() {
  if (world.getDynamicProperty("sc:cathedral_done")) return;
  const ow = overworld();
  if (!trialActive) {
    if (playersIn(TRIAL_BOX).length === 0) return;
    trialActive = true;
    ow.runCommand("fill 992 199 1064 1008 217 1064 barrier");
    ow.runCommand(`title ${TRIAL_SEL} title §c試練の間`);
    ow.runCommand(`title ${TRIAL_SEL} subtitle §7守護者を鎮めよ`);
    ow.runCommand(`playsound mob.evocation_illager.prepare_summon ${TRIAL_SEL}`);
    const pts = [
      { x: 985, y: 199, z: 1090 }, { x: 1015, y: 199, z: 1090 },
      { x: 985, y: 199, z: 1130 }, { x: 1015, y: 199, z: 1130 }
    ];
    for (const p of pts) ow.spawnEntity("sc:sky_knight", p).addTag("sc_trial");
    ow.spawnEntity("sc:sky_mage", { x: 1000, y: 200, z: 1145 }).addTag("sc_trial");
  } else {
    if (ow.getEntities({ tags: ["sc_trial"] }).length > 0) return;
    trialActive = false;
    world.setDynamicProperty("sc:cathedral_done", true);
    ow.runCommand("fill 992 199 1064 1008 217 1064 air replace barrier");
    ow.runCommand(`title ${TRIAL_SEL} title §6試練を制した`);
    ow.runCommand(`execute as ${TRIAL_SEL} run function keys/give_key`);
    ow.runCommand(`playsound ui.toast.challenge_complete ${TRIAL_SEL}`);
  }
}

// ---- ② 闘技場ウェーブ戦（3ウェーブ → 島の鍵＋素材） -----------------------
const ARENA_TRIGGER = { x1: 999, y1: 194, x2: 1001, y2: 197, z1: 1249, z2: 1251 };
const ARENA_SEL = "@a[x=982,y=194,z=1232,dx=36,dy=8,dz=36]";
const ARENA_SPAWNS = [
  { x: 990, y: 195, z: 1240 }, { x: 1010, y: 195, z: 1240 },
  { x: 990, y: 195, z: 1260 }, { x: 1010, y: 195, z: 1260 }
];
const WAVES = [
  [["sc:sky_guard", 4]],
  [["sc:sky_knight", 2], ["sc:sky_guard", 2]],
  [["sc:sky_golem", 1]]
];
let arenaWave = 0; // 0=待機, 1〜3=進行中

function spawnWave(ow, waveIdx) {
  let i = 0;
  for (const [type, count] of WAVES[waveIdx]) {
    for (let c = 0; c < count; c++) {
      const p = ARENA_SPAWNS[i % ARENA_SPAWNS.length];
      i++;
      const e = ow.spawnEntity(type, p);
      e.addTag("sc_wave");
    }
  }
  ow.runCommand(`title ${ARENA_SEL} title §cWave ${waveIdx + 1} / ${WAVES.length}`);
  ow.runCommand(`playsound mob.wither.ambient ${ARENA_SEL}`);
}

function arenaWaveTick() {
  if (world.getDynamicProperty("sc:arena_done")) return;
  const ow = overworld();
  if (arenaWave === 0) {
    if (playersIn(ARENA_TRIGGER).length === 0) return;
    arenaWave = 1;
    spawnWave(ow, 0);
  } else {
    if (ow.getEntities({ tags: ["sc_wave"] }).length > 0) return;
    if (arenaWave < WAVES.length) {
      spawnWave(ow, arenaWave);
      arenaWave++;
    } else {
      arenaWave = 0;
      world.setDynamicProperty("sc:arena_done", true);
      ow.runCommand(`title ${ARENA_SEL} title §6闘技場、制覇`);
      ow.runCommand(`execute as ${ARENA_SEL} run function keys/give_key`);
      ow.runCommand(`give ${ARENA_SEL} sc:levistone_fragment 4`);
      ow.runCommand(`playsound ui.toast.challenge_complete ${ARENA_SEL}`);
    }
  }
}

// ---- ③ 橋崩落トラップ（東幹線橋 / 渡り終えた背後が崩れる） ----------------
const BRIDGE_TRIGGER = { x1: 1150, y1: 198, x2: 1160, y2: 202, z1: 997, z2: 1003 };
const BRIDGE_STAGES = [
  "fill 1050 198 998 1066 198 1002 air replace polished_deepslate",
  "fill 1067 198 998 1083 198 1002 air replace polished_deepslate",
  "fill 1084 198 998 1100 198 1002 air replace polished_deepslate"
];

function bridgeTrapTick() {
  if (world.getDynamicProperty("sc:bridge_done")) return;
  if (playersIn(BRIDGE_TRIGGER).length === 0) return;
  world.setDynamicProperty("sc:bridge_done", true);
  const ow = overworld();
  // 予兆（Phase5共通仕様: 音→パーティクル→発動）
  ow.runCommand("playsound random.fizz @a[x=1040,y=195,z=995,dx=130,dy=10,dz=10] 1075 200 1000 1 0.6");
  ow.runCommand("particle minecraft:basic_smoke_particle 1075 199 1000");
  ow.runCommand("title @a[x=1040,y=195,z=995,dx=130,dy=10,dz=10] actionbar §c……背後の橋が軋んでいる");
  BRIDGE_STAGES.forEach((cmd, i) => {
    system.runTimeout(() => {
      try {
        ow.runCommand(cmd);
        ow.runCommand("playsound random.explode @a[x=1040,y=195,z=995,dx=130,dy=10,dz=10]");
      } catch (e) {
        console.error(`[SkyCitadel] bridge stage: ${e}`);
      }
    }, 30 + i * 15);
  });
}

// ---- ④ 封印儀式（4本柱を正しい順に起動 → 封印の床が開く） -----------------
// 正順: 北西(980,1110) → 北東(1020,1110) → 南西(980,1146) → 南東(1020,1146)
// ヒント: 各柱の足元のアメジスト数（build/citadel/seal_hints）
const PILLARS = [
  { x: 980, z: 1110 }, { x: 1020, z: 1110 },
  { x: 980, z: 1146 }, { x: 1020, z: 1146 }
];
let sealCooldown = 0;

function sealRitualTick() {
  if (world.getDynamicProperty("sc:seal_done")) return;
  if (sealCooldown > 0) {
    sealCooldown--;
    return;
  }
  const ow = overworld();
  const progress = Number(world.getDynamicProperty("sc:seal_progress") ?? 0);
  for (const pl of world.getAllPlayers()) {
    const l = pl.location;
    if (pl.dimension.id !== "minecraft:overworld") continue;
    if (l.y < 118 || l.y > 133) continue;
    for (let i = 0; i < PILLARS.length; i++) {
      const p = PILLARS[i];
      const d = (l.x - p.x) ** 2 + (l.z - p.z) ** 2;
      if (d > 9) continue; // 3ブロック以内
      if (i < progress) break; // 起動済みの柱
      sealCooldown = 4; // 連続判定の抑制（約2秒）
      if (i === progress) {
        // 正しい順序 → 柱が点灯
        ow.runCommand(`setblock ${p.x} 131 ${p.z} sea_lantern`);
        ow.runCommand(`playsound beacon.power @a[r=40] ${p.x} 131 ${p.z}`);
        world.setDynamicProperty("sc:seal_progress", progress + 1);
        ow.runCommand(`title @a[r=40] actionbar §b封印の柱 ${progress + 1} / 4`);
        if (progress + 1 >= 4) {
          world.setDynamicProperty("sc:seal_done", true);
          ow.runCommand("fill 994 118 1122 1006 118 1134 air");
          ow.runCommand("title @a[r=40] title §5封印は破られた");
          ow.runCommand("title @a[r=40] subtitle §7最深部への道が口を開く……");
          ow.runCommand("playsound mob.wither.spawn @a[r=48] 1000 120 1128");
        }
      } else {
        // 誤った順序 → リセット＋ガーゴイル
        world.setDynamicProperty("sc:seal_progress", 0);
        for (const q of PILLARS) ow.runCommand(`setblock ${q.x} 131 ${q.z} crying_obsidian`);
        ow.runCommand(`summon sc:gargoyle ${p.x} 120 ${p.z} ~ ~ sc:wake`);
        ow.runCommand(`summon sc:gargoyle ${p.x} 120 ${p.z} ~ ~ sc:wake`);
        ow.runCommand("title @a[r=40] actionbar §c封印が拒絶した——順序が違う");
        ow.runCommand(`playsound random.glass @a[r=40] ${p.x} 125 ${p.z}`);
      }
      break;
    }
  }
}

toolUseResult.originalFile:
// ============================================================
// Sky Citadel - Altherion | メインスクリプト
// Script API v2 (@minecraft/server 2.8.0)
//
// 役割分担（Phase8改善案1の方針）:
//   - HP精密監視・フェーズ管理・集団バフ → このスクリプト
//   - ゲート開放・トラップ・演出       → functions/ (mcfunction)
// ============================================================
import { world, system } from "@minecraft/server";

// ---- 定数 ------------------------------------------------------------
const BOSS_TYPE = "sc:fallen_sky_monarch";
const GUARD_TYPE = "sc:sky_guard";
const GARGOYLE_TYPE = "sc:gargoyle";

// フェーズ移行テーブル（HP閾値の昇順に全発火することで
// 瞬間大ダメージによるフェーズスキップを防ぐ）
const PHASES = [
  { hp: 375, phase: 2, event: "sc:phase2", name: "§b暴走する浮遊石の力" },
  { hp: 250, phase: 3, event: "sc:phase3", name: "§5王都を喰らう者" },
  { hp: 100, phase: 4, event: "sc:phase4", name: "§4最後の天空王" }
];

// 実行間隔（tick）— スマホ負荷対策で処理ごとに間引く（Phase9）
const BOSS_TICK = 10;    // 0.5秒: ボスHP監視
const GATE_TICK = 20;    // 1.0秒: 鍵ゲート判定
const BUFF_TICK = 40;    // 2.0秒: 近衛兵の隊列バフ
const CAP_TICK = 100;    // 5.0秒: ガーゴイル湧き上限の安全弁
const RESPAWN_TICK = 200; // 10秒: ダンジョン限定リスポーン

// ---- ダンジョン限定スポナー設定 -----------------------------------------
// バイオーム・ブロック条件に一切依存せず、ここに登録した
// エリア座標の中でのみモブが補充される（ダンジョン外では絶対に湧かない）。
// 本番アルテリオン（docs/build_plan.md）の各島に配線済み。
// center: null にするとそのエリアは無効（何も湧かない）。
const SPAWN_AREAS = [
  { name: "兵舎",     type: "sc:sky_guard",  cap: 4, radius: 24, center: { x: 1130, y: 199, z: 1180 } },
  { name: "大聖堂",   type: "sc:sky_knight", cap: 2, radius: 24, center: { x: 1000, y: 199, z: 1110 } },
  { name: "大図書館", type: "sc:sky_mage",   cap: 1, radius: 20, center: { x: 1130, y: 199, z: 820 } },
  { name: "崩壊区域", type: "sc:gargoyle",   cap: 4, radius: 24, center: { x: 860,  y: 189, z: 810 } }
];

function overworld() {
  return world.getDimension("overworld");
}

// ---- 起動 ------------------------------------------------------------
// v2: startup は早期実行フェーズ。ワールド状態には触れない（購読のみ）。
system.beforeEvents.startup.subscribe(() => {
  console.warn("[SkyCitadel] scripts loaded (startup / early execution)");
});

// v2: ワールド操作は worldLoad 以降でのみ行う。
world.afterEvents.worldLoad.subscribe(() => {
  console.warn("[SkyCitadel] world loaded - initializing systems");
  system.runInterval(safe(bossPhaseTick), BOSS_TICK);
  system.runInterval(safe(gateTick), GATE_TICK);
  system.runInterval(safe(guardFormationTick), BUFF_TICK);
  system.runInterval(safe(gargoyleCapTick), CAP_TICK);
  system.runInterval(safe(dungeonRespawnTick), RESPAWN_TICK);
  system.runInterval(safe(cathedralTrialTick), 20);
  system.runInterval(safe(arenaWaveTick), 20);
  system.runInterval(safe(bridgeTrapTick), 20);
  system.runInterval(safe(sealRitualTick), 10);
});

// 例外をコンテンツログに残す共通ラッパ（Phase10デバッグ方針）
function safe(fn) {
  return () => {
    try {
      fn();
    } catch (e) {
      console.error(`[SkyCitadel] ${fn.name}: ${e}`);
    }
  };
}

// ---- ボス: 出現時の初期名 ---------------------------------------------
world.afterEvents.entitySpawn.subscribe((ev) => {
  try {
    if (ev.entity.typeId === BOSS_TYPE && !ev.entity.nameTag) {
      ev.entity.nameTag = "§f堕ちた天空王";
    }
  } catch (e) {
    console.error(`[SkyCitadel] entitySpawn: ${e}`);
  }
});

// ---- ボス: フェーズ管理 -----------------------------------------------
function bossPhaseTick() {
  for (const boss of overworld().getEntities({ type: BOSS_TYPE })) {
    if (!boss.isValid) continue;
    const health = boss.getComponent("minecraft:health");
    if (!health) continue;
    const hp = health.currentValue;
    let phase = Number(boss.getProperty("sc:phase") ?? 1);

    // 閾値を昇順にすべて処理 → 一撃で375を大きく下回っても
    // phase2 → phase3 と順に全イベントが発火する
    for (const p of PHASES) {
      if (hp <= p.hp && phase < p.phase) {
        boss.triggerEvent(p.event);
        boss.nameTag = p.name; // ボスバー表示名を更新
        phase = p.phase;
        world.sendMessage(`§7[天空王] ${p.name} §7へと変貌した……`);
        boss.dimension.playSound("mob.wither.ambient", boss.location);
      }
    }
  }
}

// ---- ボス: 撃破演出 ----------------------------------------------------
world.afterEvents.entityDie.subscribe((ev) => {
  try {
    if (ev.deadEntity.typeId !== BOSS_TYPE) return;
    world.sendMessage("§6天空王は光となって消え、王都に静寂が戻った。");
    const ow = overworld();
    ow.runCommand('title @a title §6王都の解放者');
    ow.runCommand('title @a subtitle §7- Sky Citadel 攻略達成 -');
    ow.runCommand("playsound ui.toast.challenge_complete @a");
  } catch (e) {
    console.error(`[SkyCitadel] entityDie: ${e}`);
  }
});

// ---- 鍵ゲート判定（1秒間隔） -------------------------------------------
// 鍵5個以上を所持し、まだ開放していないプレイヤーに open_gate を実行
function gateTick() {
  overworld().runCommand(
    'execute as @a[hasitem={item=sc:island_key,quantity=5..},tag=!sc_gate_opened] at @s run function keys/open_gate'
  );
}

// ---- 近衛兵: 隊列陣形バフ（設計Phase4） --------------------------------
// 半径8ブロック以内に自分含め3体以上の近衛兵がいる場合、抵抗Iを付与
function guardFormationTick() {
  const guards = overworld().getEntities({ type: GUARD_TYPE });
  if (guards.length < 3) return; // 3体未満なら陣形は成立しない
  for (const g of guards) {
    if (!g.isValid) continue;
    const nearby = g.dimension.getEntities({
      type: GUARD_TYPE,
      location: g.location,
      maxDistance: 8
    });
    if (nearby.length >= 3) {
      // BUFF_TICKより少し長く持続させ、途切れを防ぐ
      g.addEffect("resistance", BUFF_TICK + 20, {
        amplifier: 0,
        showParticles: false
      });
    }
  }
}

// ---- ガーゴイル: 湧き上限の安全弁（Phase9: 同時6体まで） ----------------
// 魔導士の召喚が重なって溜まりすぎた場合、プレイヤーから遠い個体を消す
const GARGOYLE_CAP = 6;
function gargoyleCapTick() {
  const players = world.getAllPlayers();
  if (players.length === 0) return;
  for (const pl of players) {
    const swarm = pl.dimension.getEntities({
      type: GARGOYLE_TYPE,
      location: pl.location,
      maxDistance: 24
    });
    if (swarm.length <= GARGOYLE_CAP) continue;
    // プレイヤーから遠い順に超過分を除去
    swarm
      .sort((a, b) => dist2(b.location, pl.location) - dist2(a.location, pl.location))
      .slice(0, swarm.length - GARGOYLE_CAP)
      .forEach((g) => {
        if (g.isValid) g.remove();
      });
  }
}

function dist2(a, b) {
  const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
  return dx * dx + dy * dy + dz * dz;
}

// ---- ダンジョン限定リスポーン（spawn_rulesの代替） ----------------------
// バイオーム自然湧きを使わず、SPAWN_AREASの座標内でのみモブを補充する。
// ・プレイヤーがエリア付近にいる時だけ動く（Phase9: アクティブエリア方式）
// ・上限(cap)以下なら10秒ごとに1体だけ補充（急激な湧きを防ぐ）
// ・ガーゴイルは補充直後に自動で擬態(dormant)状態になる
let warnedUnsetAreas = false;
function dungeonRespawnTick() {
  const ow = overworld();
  const players = world.getAllPlayers();
  if (players.length === 0) return;

  let anyUnset = false;
  for (const area of SPAWN_AREAS) {
    if (!area.center) {
      anyUnset = true;
      continue;
    }
    const activationRange = (area.radius + 16) ** 2;
    const near = players.some(
      (p) => p.dimension.id === "minecraft:overworld" && dist2(p.location, area.center) <= activationRange
    );
    if (!near) continue;

    const mobs = ow.getEntities({
      type: area.type,
      location: area.center,
      maxDistance: area.radius
    });
    if (mobs.length >= area.cap) continue;

    const angle = Math.random() * Math.PI * 2;
    const r = Math.random() * area.radius * 0.5;
    ow.spawnEntity(area.type, {
      x: area.center.x + Math.cos(angle) * r,
      y: area.center.y,
      z: area.center.z + Math.sin(angle) * r
    });
  }

  if (anyUnset && !warnedUnsetAreas) {
    warnedUnsetAreas = true;
    console.warn(
      "[SkyCitadel] dungeonRespawn: 座標未設定のエリアあり（建築後にmain.jsのSPAWN_AREASへcenterを設定）"
    );
  }
}

